// iDrive customization catalog: known, reversible G30 / NBT EVO coding changes
// (the kind BimmerCode exposes), from the bundled Resources/idrive-tweaks.json
// generated by tools/make_idrive_tweaks.py. The owner applies these in
// BimmerCode; BMW Link only reads coding, it never writes it.
import Foundation

public struct IDriveTweak: Codable, Equatable, Identifiable, Sendable {
    public enum Risk: String, Codable, Sendable { case green, amber }

    public let id: String
    public let title: String
    public let category: String
    public let module: String
    /// Diagnostic address of the module, so the app can tell you whether your
    /// car answered for it in a scan.
    public let moduleAddress: UInt16
    public let what: String
    public let why: String
    /// Where to make the change in BimmerCode.
    public let how: String
    public let undo: String
    public let risk: Risk
    /// A real caveat (legality, distraction, wear), or nil.
    public let caveat: String?
    /// Equipment the car needs for the option to exist, or nil.
    public let needs: String?

    public var reversible: Bool { true }
}

public struct IDriveCatalog: Sendable {
    public let version: Int
    public let categories: [String]
    public let tweaks: [IDriveTweak]

    public init(version: Int, categories: [String], tweaks: [IDriveTweak]) {
        self.version = version
        self.categories = categories
        self.tweaks = tweaks
    }

    /// The catalog shipped with the app. Empty (never a crash) if it can't load.
    public static let shared = IDriveCatalog.loadBundled()

    public static func loadBundled() -> IDriveCatalog {
        guard let url = Bundle.module.url(forResource: "idrive-tweaks", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let catalog = try? decode(data) else {
            return IDriveCatalog(version: 0, categories: [], tweaks: [])
        }
        return catalog
    }

    public static func decode(_ data: Data) throws -> IDriveCatalog {
        struct File: Decodable { let version: Int; let categories: [String]; let tweaks: [IDriveTweak] }
        let file = try JSONDecoder().decode(File.self, from: data)
        return IDriveCatalog(version: file.version, categories: file.categories, tweaks: file.tweaks)
    }

    public func tweaks(in category: String) -> [IDriveTweak] { tweaks.filter { $0.category == category } }

    /// Categories that actually have at least one tweak, in catalog order.
    public var usedCategories: [String] { categories.filter { !tweaks(in: $0).isEmpty } }

    public func tweak(_ id: String) -> IDriveTweak? { tweaks.first { $0.id == id } }

    /// The distinct module addresses the catalog touches.
    public var moduleAddresses: Set<UInt16> { Set(tweaks.map(\.moduleAddress)) }
}

public extension IDriveTweak {
    /// Did the car answer for this tweak's module in a scan? Helps the owner see
    /// the change is relevant to a module their car actually has.
    func moduleAnswered(in scan: CodeScan?) -> Bool? {
        guard let scan else { return nil }
        return scan.modules.contains { $0.address == moduleAddress && $0.answered }
    }
}
